#define STATIC_HEAP_SIZE 1024
#define ALIGN_FLOOR(addr, type) (((uint32_t)(addr)) & ~(uint32_t)(sizeof(type) - 1))
#define ALIGN_CEIL(addr, type) ALIGN_FLOOR((uint32_t)(addr) + sizeof(type) - 1, type)
