/* ---- HAL callbacks -------------------------------------------------------------------------------- */

void HAL_I2C_MasterTxCpltCallback(I2C_HandleTypeDef *hi2c) {
  assert(hi2c == &hi2c1);
  ucDrvI2cCallback(drv_i2c);
}

void HAL_I2C_MasterRxCpltCallback(I2C_HandleTypeDef *hi2c) {
  assert(hi2c == &hi2c1);
  ucDrvI2cCallback(drv_i2c);
}

static void HAL_DMA_MasterCpltCallback(DMA_HandleTypeDef *hdma) {
  assert(hdma == &hdma_memtomem_dma2_stream0);
  ucDrvDmaCallback(drv_dma);
}

void HAL_LTDC_ReloadEventCallback(LTDC_HandleTypeDef *hltdc_) {
  (void)hltdc_;
  display_reload_callback();
}

/* printf() goes to USART1 = the ST-LINK virtual COM port, 115200 baud */
int __io_putchar(int ch) {
  HAL_UART_Transmit(&huart1, (uint8_t *)&ch, 1, HAL_MAX_DELAY);
  return ch;
}

/* ---- main ----------------------------------------------------------------------------------------- */

int main(void) {
  MPU_Config();
  SCB_EnableICache();
  SCB_EnableDCache();
  HAL_Init();
  SystemClock_Config();

  MX_GPIO_Init();
  MX_DMA_Init();
  MX_FMC_Init();
  MX_I2C3_Init();
  MX_I2C1_Init();
  MX_DCMI_Init();
  MX_LTDC_Init();
  MX_USART1_UART_Init();
  MX_TIM1_Init();
  MX_TIM2_Init();

  /* The RTOS drivers are created before the scheduler runs; HAL_Delay() needs a SysTick priority above
     the (not yet started) kernel's for that. */
  HAL_InitTick(4);
  assert(xDrvI2cCreate(&hi2c1, pvStaticAllocate, &drv_i2c) == pdTRUE);
  assert(xDrvDmaCreate(&hdma_memtomem_dma2_stream0, pvStaticAllocate, &drv_dma) == pdTRUE);
  HAL_DMA_RegisterCallback(&hdma_memtomem_dma2_stream0, HAL_DMA_XFER_CPLT_CB_ID, HAL_DMA_MasterCpltCallback);
  HAL_InitTick(15);
  setvbuf(stdout, NULL, _IONBF, 0); /* printf() lines reach the serial port at once */

#ifdef NN_BENCH
  person_nn_bench(); /* time the network on its test image first (tools/nn_bench.py reads the result) */
#endif

  osKernelInitialize();
  osThreadNew(events_task, NULL, &events_task_attr);
  osThreadNew(display_task, NULL, &display_task_attr);
  osThreadNew(detector_task, NULL, &detector_task_attr);
  osThreadNew(sd_task, NULL, &sd_task_attr);
  osKernelStart();
  for (;;) {
  }
}

/* ---- memory protection ---------------------------------------------------------------------------- */

/* The SDRAM (0xC0000000, 8 MB) is "device" memory by default: not cached, but unaligned accesses fault, and
   the compiler happily merges two neighbouring byte stores into one unaligned halfword store. Both halves
   therefore become "normal" memory:
     lower 4 MB, frame buffers (BufferSection): not cached, so the LTDC and the DMA always see what the CPU wrote
     upper 4 MB, network tensors and pictures (NN_Arena): cached, write-back, only the CPU touches them */
static void MPU_Config(void) {
  MPU_Region_InitTypeDef r = {0};
  HAL_MPU_Disable();
  r.Enable = MPU_REGION_ENABLE;
  r.Number = MPU_REGION_NUMBER0;
  r.BaseAddress = 0xC0000000;
  r.Size = MPU_REGION_SIZE_4MB;
  r.SubRegionDisable = 0x0;
  r.TypeExtField = MPU_TEX_LEVEL1;
  r.AccessPermission = MPU_REGION_FULL_ACCESS;
  r.DisableExec = MPU_INSTRUCTION_ACCESS_DISABLE;
  r.IsShareable = MPU_ACCESS_NOT_SHAREABLE;
  r.IsCacheable = MPU_ACCESS_NOT_CACHEABLE;
  r.IsBufferable = MPU_ACCESS_NOT_BUFFERABLE;
  HAL_MPU_ConfigRegion(&r);
  r.Number = MPU_REGION_NUMBER1;
  r.BaseAddress = 0xC0400000;
  r.IsCacheable = MPU_ACCESS_CACHEABLE;
  r.IsBufferable = MPU_ACCESS_BUFFERABLE;
  HAL_MPU_ConfigRegion(&r);
  HAL_MPU_Enable(MPU_PRIVILEGED_DEFAULT);
}

