  RCC_OscInitStruct.PLL.PLLM = 25;
  RCC_OscInitStruct.PLL.PLLN = 432; /* 216 MHz (over-drive); was 192 with PLLM 12 = 200 MHz */
  RCC_OscInitStruct.PLL.PLLP = RCC_PLLP_DIV2;
  RCC_OscInitStruct.PLL.PLLQ = 9; /* PLL48CLK = 432/9 = 48 MHz: SDMMC kernel clock (CubeMX had 2 = 200 MHz, far out of spec) */
